+// Sales from the till: each ticket sells dishes, each dish uses one recipe
+// portion per unit sold. Sales are kept so reports can compare theory to use.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a sale with this ticket number was already recorded. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Records one sold line and consumes its ingredients (ref `sale:<ticket>`). */
+export function sell(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const uses = scaled(getRecipe(store, dish.recipeId), qty);
+  for (const u of uses) consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const sale = { ticket, soldAt, dishId, qty, uses };
+  store.data.sales.push(sale);
+  return sale;
+}
+
+/** Theoretical vs actual use per item for sales days from..to (inclusive). */
+export function variance(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must not be after to" });
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  const inRange = (at) => at.slice(0, 10) >= from && at.slice(0, 10) <= to;
+  for (const s of store.data.sales ?? [])
+    if (inRange(s.soldAt)) for (const u of s.uses) row(u.itemId).theoretical += u.qty;
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...rows]
+    .map(([itemId, v]) => ({
+      itemId,
+      name: store.data.items.find((i) => i.id === itemId)?.name,
+      theoretical: r3(v.theoretical),
+      actual: r3(v.actual),
+      difference: r3(v.actual - v.theoretical),
+    }))
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
